<section x-show="tab==='visuals'" x-cloak x-data="sceneEditor(@js(['url'=>route('visuals.show',[$story,$page]),'generate'=>route('images.generate',[$story,$page]),'upload'=>route('assets.store',$story),'model'=>$story->image_model,'prompt'=>$page->scene_prompt]))">
<p x-show="halted" class="text-sm">Copy unsaved changes and reload to load the latest version.</p>
<div x-show="!loading" class="space-y-3">

<p x-show="!document.visuals.length" class="rounded-xl border border-dashed p-5 text-sm">Start with a scene background. Add the note as a separate object, then create another scene or close-up for the opened stone and key.</p>
<div class="flex flex-wrap items-end gap-2 visual-toolbar"><label class="field min-w-0 flex-1 basis-56">Current visual<select :value="selected" @change="selectVisualOption($event.target.value);$event.target.value=selected"><option value="new:scene">+ New scene</option><option value="new:object">+ New object / close-up</option><option value="" disabled>Select a visual</option><template x-for="(v,index) in document.visuals" :key="v.id"><option :value="v.id" :selected="v.id===selected" x-text="(index+1)+'. '+(v.kind==='scene'?'Scene · ':'Object · ')+v.name"></option></template></select></label><button type="button" class="btn-secondary shrink-0" @click="editingVisual=!editingVisual" :disabled="!visual || !visual.asset_id" :aria-expanded="visualDetailsVisible" x-text="editingVisual?'Done editing':'Edit'"></button><button type="button" class="btn-secondary shrink-0" @click="requestVisualName('duplicate')" :disabled="!visual">Duplicate visual</button><button type="button" class="btn-secondary shrink-0" @click="requestVisualDelete()" :disabled="!visual" aria-haspopup="dialog">Delete visual</button></div>
<template x-if="visual"><div class="space-y-3">
<div x-show="visualDetailsVisible" class="space-y-3">
<div class="grid gap-3 md:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)]"><label class="field min-w-0">Visual name<input x-model="visual.name" @input="changed()" maxlength="160"></label><label class="field">Visual type<select :value="visual.kind" @change="requestVisualType($event.target.value);$event.target.value=visual.kind"><option value="scene">Scene</option><option value="object">Object / close-up</option></select></label><div class="field"><span>Selected image</span><button type="button" class="btn-secondary min-w-0 justify-start gap-3" @click="openVisualImagePicker()" aria-haspopup="dialog"><img x-show="asset(visual.asset_id)" :src="asset(visual.asset_id)?.url" alt="" class="h-9 w-12 shrink-0 rounded object-contain"><span class="truncate" x-text="asset(visual.asset_id)?.name || 'Choose image'"></span></button></div></div>
<label class="field">Description<textarea x-model="visual.description" @input="changed()" maxlength="3000" placeholder="Describe this scene or object for the player."></textarea></label>
</div>
<div class="rounded-xl border border-stone-200 dark:border-stone-700 bg-white dark:bg-stone-900 p-4 space-y-4">
<div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-serif text-xl" x-text="preview?'Interaction preview':visual.kind==='scene'?'Clickable areas':'Object image'"></h3><div class="flex gap-2"><button type="button" x-show="!preview && visual.kind==='scene'" @click="toggleDrawing()" class="btn-secondary" x-text="drawing?'Cancel drawing':'Draw area'"></button><button type="button" x-show="preview" @click="preview=false;modal=null" class="btn-secondary">Exit preview</button></div></div>
<p class="text-xs text-stone-500" x-show="drawing">Drag to draw an area. Select an area to move it, resize its corners, or double-click its label to rename it.</p>
<template x-if="asset(visual?.asset_id)"><div data-scene-canvas class="relative w-full select-none" :class="drawing?'cursor-crosshair touch-none':''" @pointerdown="startDraw($event)" @pointermove="moveDraw($event)" @pointerup="endDraw($event)" @pointercancel="cancelDraw()" @lostpointercapture="if(drag)cancelDraw()" @keydown.escape.window="if(drawing)cancelDraw()">
<img :src="asset(visual.asset_id).url" :alt="visual.name" class="block w-full h-auto rounded-lg" draggable="false"><button type="button" class="image-zoom-button" x-show="!drawing && !preview" @pointerdown.stop :aria-label="'Enlarge '+visual.name" @click.stop="enlarge(asset(visual.asset_id))" title="Zoom image"><x-zoom-icon /></button>
<template x-if="drawRect"><div data-draw-preview class="pointer-events-none absolute z-30 rounded border-2 border-dashed border-amber-400 bg-amber-300/25" :style="style(drawRect)" aria-hidden="true"></div></template>
<template x-for="h in visual.hotspots" :key="h.id"><div :style="style(h)" class="absolute rounded border-2 focus:ring-2 focus:ring-amber-400" :class="[preview?'border-transparent hover:border-amber-400':hotspotId===h.id?'z-10 border-amber-500 bg-amber-300/30':'border-amber-400 bg-amber-300/10',drawing?'pointer-events-none':'',!preview?'cursor-move touch-none':'cursor-pointer']" role="button" tabindex="0" :aria-label="h.label" :aria-pressed="!preview && hotspotId===h.id" @pointerdown.stop="startArea($event,h)" @pointermove.stop="moveArea($event)" @pointerup.stop="endArea()" @pointercancel.stop="endArea(true)" @keydown="areaKey($event,h)" @keydown.enter.self.prevent="activate(h)" @click.stop="activate(h)">
<template x-if="h.overlay && visualAsset(h.object_id)"><img :src="visualAsset(h.object_id).url" alt="" class="pointer-events-none h-full w-full object-contain" draggable="false"></template>
<span x-show="!preview && renamingId!==h.id" class="absolute left-0 top-0 max-w-full truncate bg-stone-900/90 px-1 text-xs text-white" @pointerdown.stop @dblclick.stop="beginRename(h)" x-text="h.label"></span>
<template x-if="renamingId===h.id && !preview"><input class="absolute left-0 top-0 z-30 w-40 rounded border-amber-500 bg-white p-1 text-xs text-stone-900" aria-label="Area name" maxlength="160" x-model="labelDraft" x-init="$nextTick(()=>{$el.focus();$el.select();})" @pointerdown.stop @click.stop @keydown.stop @keydown.enter.prevent="finishRename(h)" @keydown.escape.prevent="renamingId=''" @blur="finishRename(h)"></template>
<template x-if="!preview && hotspotId===h.id"><div>
<template x-for="corner in ['nw','ne','sw','se']" :key="corner"><button type="button" class="absolute z-20 h-3 w-3 rounded-sm border border-white bg-amber-600 touch-none" :style="(corner.includes('n')?'top:-6px;':'bottom:-6px;')+(corner.includes('w')?'left:-6px;':'right:-6px;')+'cursor:'+corner+'-resize'" :aria-label="'Resize '+h.label+' '+corner" @pointerdown.stop="startArea($event,h,corner)" @pointermove.stop="moveArea($event)" @pointerup.stop="endArea()" @pointercancel.stop="endArea(true)" @click.stop></button></template>
<button type="button" class="absolute bottom-1 right-1 z-20 grid h-7 w-7 place-items-center rounded bg-red-700 text-white hover:bg-red-800" :aria-label="'Delete '+h.label" @pointerdown.stop @click.stop="requestAreaDelete(h.id)"><svg viewBox="0 0 24 24" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/></svg></button>
</div></template>
</div></template>
</div></template>
<p x-show="!asset(visual?.asset_id)" class="py-8 text-center text-sm text-stone-500">Choose an image above to start placing clickable areas.</p>

</div>
<section x-show="visual.kind==='object'" class="space-y-3 rounded-xl border border-stone-200 p-4 dark:border-stone-700">
<div class="flex items-center justify-between gap-3"><h3 class="font-serif text-xl">Inventory actions</h3><button type="button" class="btn-secondary" @click="addObjectAction()" :disabled="(visual.actions||[]).length>=50">+ Action</button></div>
<p class="text-xs text-stone-500">Each action replaces this inventory item with another object. Create its image as an object visual, then link it here. Link back to earlier objects for reversible actions.</p>
<template x-for="action in visual.actions||[]" :key="action.id"><div class="flex flex-wrap items-end gap-3"><label class="field min-w-0 flex-1">Action name<input x-model="action.label" @input="changed()" maxlength="160" placeholder="Open, close, crumple…"></label><label class="field min-w-0 flex-1">Replace with<select x-model="action.target_id" @change="changed()"><option :value="null">Choose object</option><template x-for="(object,index) in objects" :key="object.id"><option :value="object.id" x-text="(index+1)+'. '+object.name"></option></template></select></label><button type="button" class="btn-secondary" @click="removeObjectAction(action.id)" :aria-label="'Remove action '+action.label">Remove</button></div></template>
<p x-show="!(visual.actions||[]).length" class="text-xs text-stone-500">No actions yet.</p>
</section>
<div x-show="!preview && visual.kind==='scene'" class="space-y-3"><p x-show="!hotspot" class="text-sm text-stone-500">Select an area on the image to edit its interaction.</p>
<template x-if="hotspot"><div class="rounded-xl border border-stone-200 dark:border-stone-700 p-4 space-y-4">
<h3 class="font-semibold" x-text="hotspot.label"></h3><label class="field" x-show="hotspot.action==='examine'">Description<textarea x-model="hotspot.description" @input="changed()" maxlength="3000" placeholder="What does the player see or discover?"></textarea></label>
<label class="field">Click action<select x-model="hotspot.action" @change="changed()"><option value="examine">Examine — show description</option><option value="inspect">Inspect — show object image</option><option value="transition">Change scene state</option><option value="pickup">Pick up object</option><option value="inventory">Use inventory on area</option><option value="choices">Choose an action</option><option value="next_page">Move to next page</option></select></label>
@include('studio.area-actions')
<div class="field" x-show="['inspect','pickup','transition'].includes(hotspot.action)"><span>Object image</span><button type="button" class="btn-secondary justify-start gap-3" aria-haspopup="dialog" @click="openInteractionPicker('object')"><img x-show="visualAsset(hotspot.object_id)" :src="visualAsset(hotspot.object_id)?.url" alt="" class="h-10 w-14 object-contain"><span x-text="visualAsset(hotspot.object_id)?.name || 'Choose object image'"></span></button></div>

<div class="field" x-show="['inspect','pickup','transition'].includes(hotspot.action)"><span>Scene after click</span><button type="button" class="btn-secondary justify-start gap-3 text-left" aria-haspopup="dialog" @click="openInteractionPicker('scene')"><img x-show="visualAsset(hotspot.target_id)" :src="visualAsset(hotspot.target_id)?.url" alt="" class="h-10 w-14 object-contain"><span x-text="scenes.find(v=>v.id===hotspot.target_id)?sceneLabel(scenes.find(v=>v.id===hotspot.target_id)):'Keep current scene'"></span></button></div>
</div></template></div>

</div></template></div>
<dialog x-ref="visualTypeDialog" class="reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="visual-type-title">
<div class="space-y-4 p-5"><h2 id="visual-type-title" class="font-serif text-xl">Change visual type?</h2><p class="text-sm" x-text="typeChange?.message"></p><p class="text-sm">The image, name, and prompt will be kept.</p><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" autofocus @click="typeChange=null;$refs.visualTypeDialog.close()">Cancel</button><button type="button" class="btn-primary" @click="confirmVisualType()">Change type</button></div></div></dialog>
<dialog x-ref="visualNameDialog" class="reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="visual-name-title">
<form class="space-y-4 p-5" @submit.prevent="createNamedVisual()"><h2 id="visual-name-title" class="font-serif text-xl" x-text="visualAction==='duplicate'?'Duplicate visual':visualAction==='scene'?'New scene state':'New object / close-up'"></h2><label class="field">Name<input x-ref="visualNameInput" x-model="visualName" required maxlength="160" autocomplete="off"></label><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" @click="$refs.visualNameDialog.close()">Cancel</button><button type="submit" class="btn-primary" x-text="visualAction==='duplicate'?'Duplicate':'Create'"></button></div></form></dialog>
<dialog x-ref="deleteVisualDialog" class="reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="delete-visual-title">
<div class="space-y-4 p-5"><h2 id="delete-visual-title" class="font-serif text-xl">Delete visual?</h2><p class="font-semibold" x-text="deletingVisual?.name"></p><p class="text-sm">This removes the visual and its clickable areas. Images remain in your library.</p><p x-show="dependentAreas" class="text-sm" x-text="dependentAreas+' interaction(s) link to this visual. Those links will be cleared; affected actions will become Examine where needed.'"></p><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" autofocus @click="$refs.deleteVisualDialog.close()">Cancel</button><button type="button" class="rounded-lg bg-red-700 px-4 py-2 text-sm text-white" @click="confirmVisualDelete()">Delete visual</button></div></div></dialog>
<dialog x-ref="deleteAreaDialog" class="reference-dialog max-w-sm rounded-xl bg-white p-5 text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="delete-area-title">
<div class="p-5"><h2 id="delete-area-title" class="font-serif text-xl">Delete clickable area?</h2><p class="my-4 text-sm" x-text="visual?.hotspots.find(h=>h.id===deleteAreaId)?.label"></p><p x-show="areaObjectToDelete" class="mb-4 text-sm" x-text="'The linked object visual ‘'+(areaObjectToDelete?.name || '')+'’ will also be deleted. Generated images remain in your library.'"></p><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" autofocus @click="$refs.deleteAreaDialog.close()">Cancel</button><button type="button" class="rounded-lg bg-red-700 px-4 py-2 text-sm text-white" @click="confirmAreaDelete()">Delete area</button></div></div></dialog>
<dialog x-ref="interactionImagePicker" class="reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="interaction-picker-title">
<header class="flex items-center justify-between border-b p-4 dark:border-stone-700"><h2 id="interaction-picker-title" class="font-serif text-xl" x-text="pickerKind==='object'?'Choose object image':'Choose next scene'"></h2><button type="button" class="btn-secondary" @click="$refs.interactionImagePicker.close()">Close</button></header>
<div class="max-h-[60dvh] overflow-y-auto p-4">
<label class="field border-b border-stone-200 px-4 py-3 dark:border-stone-700" x-show="pickerKind==='object'">Images from<select x-model="imagePickerPage"><template x-for="p in previewPages" :key="p.id"><option :value="String(p.id)" x-text="pageImageLabel(p)+(p.id===editorPageId?' (current page)':'')"></option></template><option value="uploads">Uploaded references (unassigned)</option></select></label>
<div x-show="pickerKind==='object'" class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="a in pickerAssets" :key="a.id"><button type="button" class="rounded-lg border p-2 text-left dark:border-stone-700" :class="visualAsset(hotspot?.object_id)?.id===a.id?'ring-2 ring-amber-500':''" @click="selectObjectImage(a.id)"><img :src="a.url" :alt="a.name" loading="lazy" class="aspect-square w-full object-contain"><span class="text-xs break-words" x-text="a.name"></span></button></template><p x-show="!pickerAssets.length" class="col-span-full text-sm">Upload or generate an object image first.</p></div>
<div x-show="pickerKind==='scene'" class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="v in scenes.filter(v=>v.id!==selected)" :key="v.id"><button type="button" class="rounded-lg border p-2 text-left dark:border-stone-700" :class="hotspot?.target_id===v.id?'ring-2 ring-amber-500':''" @click="if(hotspot){hotspot.target_id=v.id;changed();$refs.interactionImagePicker.close();}"><img x-show="asset(v.asset_id)" :src="asset(v.asset_id)?.url" :alt="v.name" loading="lazy" class="aspect-square w-full object-contain"><span class="block text-xs break-words" x-text="sceneLabel(v)"></span></button></template><p x-show="scenes.length<2" class="col-span-full text-sm">Add another scene state to create a destination.</p></div>
</div><footer class="border-t p-4 dark:border-stone-700"><button type="button" class="btn-secondary" @click="if(hotspot){if(pickerKind==='object'){hotspot.object_id=null;hotspot.overlay=false;if(['inspect','pickup'].includes(hotspot.action))hotspot.action='examine';}else{hotspot.target_id=null;if(hotspot.action==='transition')hotspot.action='examine';}changed();$refs.interactionImagePicker.close();}" x-text="pickerKind==='object'?'No object image':'Keep current scene'"></button></footer></dialog>
<dialog x-ref="visualImagePicker" class="image-picker-dialog reference-dialog rounded-2xl border border-stone-200 bg-white text-stone-900 shadow-xl dark:border-stone-700 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="visual-image-picker-title" @click="if($event.target===$el)$el.close()">
<div class="flex max-h-[85dvh] flex-col">
<header class="flex items-center justify-between gap-3 border-b border-stone-200 p-4 dark:border-stone-700"><h2 id="visual-image-picker-title" class="font-serif text-xl">Choose an image</h2><button type="button" class="btn-secondary" @click="$refs.visualImagePicker.close()">Close</button></header>
<label class="field border-b border-stone-200 px-4 py-3 dark:border-stone-700">Images from<select x-model="imagePickerPage"><template x-for="p in previewPages" :key="p.id"><option :value="String(p.id)" x-text="pageImageLabel(p)+(p.id===editorPageId?' (current page)':'')"></option></template><option value="uploads">Uploaded references (unassigned)</option></select></label>
<div class="min-h-0 overflow-y-auto p-4">
<p x-show="!pickerAssets.length" class="py-8 text-center text-sm text-stone-500">No images yet. Upload references or generate an image first.</p>
<div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="a in pickerAssets" :key="a.id"><button type="button" class="overflow-hidden rounded-xl border text-left focus:outline-none focus:ring-2 focus:ring-amber-500" :class="visual?.asset_id===a.id?'border-amber-500 ring-2 ring-amber-500':'border-stone-200 dark:border-stone-700'" :aria-pressed="visual?.asset_id===a.id" :aria-label="'Select '+a.name" @click="if(visual){useImage(a.id);preview=false;$refs.visualImagePicker.close();}">
<img :src="a.url" :alt="a.name" loading="lazy" class="aspect-square w-full bg-stone-100 object-contain dark:bg-stone-950"><span class="block break-words p-2 text-xs" x-text="a.name"></span><span x-show="visual?.asset_id===a.id" class="block px-2 pb-2 text-xs font-semibold text-amber-700 dark:text-amber-300">Selected</span>
</button></template></div>
</div><footer class="flex justify-between gap-3 border-t border-stone-200 p-4 dark:border-stone-700"><button type="button" class="btn-secondary" :disabled="!visual?.asset_id" @click="if(visual){visual.asset_id=null;preview=false;changed();$refs.visualImagePicker.close();}">Remove selection</button><a class="btn-secondary" href="{{ route('images.studio',[$story,$page]) }}" :href="'{{ route('images.studio',[$story,$page]) }}'+(window.vsgSceneEditor?.visual?'?visual='+encodeURIComponent(window.vsgSceneEditor.visual.id):'')" @click.prevent="window.vsgSceneEditor?.openGeneration('{{ route('images.studio',[$story,$page]) }}',false)">Generate an image</a></footer>
</div></dialog>
@include('studio.preview')
</section>
